            el: document.getElementById('phone'),
            error: document.getElementById('phoneError'),
            validate: (val) => {
                if (!val.trim()) return ''; // Optional
                // Basic check for format if user typed something
                return val.length >= 7 ? '' : 'Please enter a valid phone number';
            }
        }
    };

    const validateField = (name) => {
        const field = inputs[name];
        const errorMessage = field.validate(field.el.value);
        field.error.textContent = errorMessage;

        if (errorMessage) {
            field.el.classList.add('invalid');
            return false;
        } else {
            field.el.classList.remove('invalid');
            return true;
        }
    };

    form.addEventListener('submit', (e) => {
        e.preventDefault();

        let isValid = true;
        Object.keys(inputs).forEach(name => {
            if (!validateField(name)) {
                isValid = false;
            }
        });

        if (isValid) {
            form.classList.add('hidden');
            successMessage.classList.remove('hidden');
            console.log('Form submitted successfully:', {
                name: inputs.fullName.el.value,
                email: inputs.email.el.value,
                phone: inputs.phone.el.value
            });
        }
    });

    // Clear error on input
    Object.keys(inputs).forEach(name => {
        inputs[name].el.addEventListener('input', () => {
            if (inputs[name].el.classList.contains('invalid')) {
                validateField(name);
            }
        });
    });
});
